products.css:
/*===== CHECKOUT STYLE 1 =====*/
.primary-btn { background: var(--primary); color: var(--white); box-shadow: var(--shadow-2); padding: 12px 26px; border-radius: 6px; font-weight: 600; border: none; }
.primary-btn:hover { background: var(--primary-dark); color: var(--white); box-shadow: var(--shadow-4); }
.outline-btn { border: 1.5px solid var(--primary); color: var(--primary); padding: 11px 24px; border-radius: 6px; font-weight: 600; background: transparent; }
.outline-btn:hover { background: var(--primary); color: var(--white); }
.checkout-style-2 { background: var(--white); padding: 60px 0; }
.checkout-style-2 .checkout-card { background: var(--light-3); border: 1px solid var(--gray-4); border-radius: 12px; padding: 30px; box-shadow: var(--shadow-2); color: var(--black); }
.checkout-style-2 h4 { color: var(--black); }
.checkout-style-2 .form-label { font-weight: 500; font-size: 14px; color: var(--dark-3); }
.checkout-style-2 .form-control { padding: 11px 14px; border-radius: 8px; border: 1px solid var(--gray-4); }

/*===== CHECKOUT STYLE 2 =====*/
.primary-btn { background: var(--secondary); color: var(--white); box-shadow: var(--shadow-2); padding: 12px 26px; border-radius: 6px; font-weight: 600; border: none; }
.primary-btn:hover { background: var(--secondary-dark); color: var(--white); box-shadow: var(--shadow-4); }
.outline-btn { border: 1.5px solid var(--secondary); color: var(--secondary); padding: 11px 24px; border-radius: 6px; font-weight: 600; background: transparent; }
.outline-btn:hover { background: var(--secondary); color: var(--white); }
.checkout-style-3 { background: var(--light-2); padding: 60px 0; }
.checkout-style-3 .checkout-card { background: var(--white); border: 1px solid var(--gray-4); border-radius: 12px; padding: 30px; box-shadow: var(--shadow-2); color: var(--black); }
.checkout-style-3 h4 { color: var(--black); }
.checkout-style-3 .form-label { font-weight: 500; font-size: 14px; color: var(--dark-2); }
.checkout-style-3 .form-control { padding: 11px 14px; border-radius: 8px; border: 1px solid var(--gray-4); }
